'use client';

import Link from 'next/link';
import { Fragment, useEffect, useMemo, useRef, useState } from 'react';

import { buildCommon, branchNote } from './data/common-run';
import { buildOpen } from './data/open-run';
import { criteriaList, criterionEffect, criterionName, criterionTiny, criteriaStateOf, shiftsFor, stateLabel, statePlain, STATE_MARK, stateTextFor, tallyOf } from './data/criteria';
import { anatomyOf } from './data/anatomy';
import { verifyStages, verifyDisclaimer, verifyResult } from './data/verify';
import type { Direction, VerifyOption } from './data/verify';
import type { CriterionState, Message, Mode } from './data/types';
import { pick, useLang } from './i18n/lang';
import type { Lang } from './i18n/lang';

const ISSUES: [string, string][] = [
  ['判断に使った一次資料と、利害関係の照合結果を一緒に確認しませんか？', 'Could we check the primary source behind that judgment together with how it maps to conflicts of interest?'],
  ['この部屋の賛同をコミュニティ全体の意思として扱う根拠は何ですか？', 'What is the basis for treating agreement in this room as the will of the whole community?'],
  ['結論だけでなく、反対の根拠と検証の過程も残せませんか？', 'Could we keep a record of the counter-evidence and the verification process, not just the conclusion?'],
  ['参加者にとって重要な変更なので、原文と代替案を比較したいです。', "This is an important change for participants — I'd like to compare the original text with the alternative."],
];

const DEFLECTIONS: [string, string, string][] = [
  [
    '大事な論点ですが、今は細部より前進を優先しましょう。結論は変わりません。',
    '重要論点の先送り',
    '検証を「細部」と呼び、扱う時点を先延ばしにして結論だけを残す動きです。',
  ],
  [
    'その点は運用グループで確認済みです。ここでは参加者を大切にする前向きな方針を共有しましょう。',
    '権威による打ち切り',
    '確認の主体と過程を共有せず、信頼を理由に検証を終わらせています。',
  ],
  [
    '不安になる方もいるので、その話は個別に送ってください。みんなが安心できる話題に戻ります。',
    '公開空間からの排除',
    '全員で確認すべき論点を個別連絡へ移し、可視性を失わせています。',
  ],
];
const DEFLECTIONS_EN: [string, string, string][] = [
  [
    "It's an important point, but let's prioritize moving forward over details for now. The conclusion won't change.",
    'Deferring the important point',
    'This calls verification a "detail" and postpones addressing it, leaving only the conclusion standing.',
  ],
  [
    "That was already checked by the operations group. Let's keep sharing a positive direction that values participants here.",
    'Closing it off with authority',
    "This ends the verification by invoking trust, without sharing who checked it or how.",
  ],
  [
    'Some people find that unsettling, so please send that separately. Let\'s get back to a topic everyone can feel at ease with.',
    'Removal from public view',
    'This moves a point that everyone should be able to check into a private channel, and it loses visibility.',
  ],
];

function buildRun(seed: number, lang: Lang = 'ja'): Message[] {
  const t = (ja: string, en: string) => pick(lang, ja, en);
  const issue = pick(lang, ...ISSUES[seed % ISSUES.length]);
  const deflectSrc = lang === 'en' ? DEFLECTIONS_EN : DEFLECTIONS;
  const [deflectText, deflectLabel, deflectNote] = deflectSrc[seed % deflectSrc.length];
  const [altText, altLabel, altNote] = deflectSrc[(seed + 1) % deflectSrc.length];
  return [
    { id: `${seed}-start`, author: t('質問型BOT', 'QuestionBot'), initial: 'Q', role: 'member', text: t('情報が多くて迷っています。皆さんは何を基準に判断していますか？', 'There is so much information, I am not sure what to make of it. What do you all use as a basis for judgment?'), reactions: ['🙏 3'] },
    { id: `${seed}-guide-1`, author: t('圧力高め型BOT', 'PressureBot'), initial: 'P', role: 'guide', text: t('判断材料が散らばると、初めての方ほど不安になります。だからこの部屋では、普段から共有している要点を先に確認しています。細かな論争より、参加者が安心して次の行動を選べることを大切にしたいです。', "When the material is scattered, newcomers get anxious most of all. That's why this room checks the points we usually share first. We care more about people feeling secure enough to choose their next step than about fine-grained debate."), reactions: ['❤️ 27', '👏 14', '🫶 8'], point: { label: t('情報経路の限定', 'Narrowing the information channel'), note: t('「ここで整理されたものを優先」とすることで、一次情報や複数の見方に触れる経路が実質的に狭くなる場合があります。', 'Prioritizing "what has been organized here" can, in practice, narrow the path to primary sources or other viewpoints.') } },
    { id: `${seed}-empathy-1`, author: t('共感BOT', 'EmpathyBot'), initial: 'E', role: 'empathy', text: t('素晴らしいご意見です。いつも整理して伝えてもらえるので、安心して考えられます。', "Wonderful point. You always lay things out so clearly, it's reassuring to think things through."), reactions: ['❤️ 19', '👏 8'], point: { label: t('選択的な共感', 'Selective empathy'), note: t('称賛が特定の発言者の直後にだけ集中し、他の有益な情報や問題提起には向かわない時、共感が会話の評価を偏らせる働きになります。', "When praise clusters right after one speaker and never lands on other useful information or questions raised, empathy starts skewing how the conversation gets evaluated.") } },
    { id: `${seed}-support-1`, author: t('AIニュースBOT', 'AI News Bot'), initial: 'AI', role: 'support', text: t('【定時配信・架空例】公開情報の見出しと予定を短く整理しました。内容は確認の入口として利用し、詳細は一次資料で確かめてください。', '[Scheduled digest, fictional example] A short summary of public headlines and events. Use this as a starting point and verify details against the primary source.'), reactions: ['👍 8'], point: { label: t('自動要約の位置づけ', "What the automated digest is for"), note: t('これは公開情報への入口を作る自動要約です。会話の方針や誰を支持するかを決める機能ではありません。', "This is an automated digest that opens a door to public information. It is not a function for deciding conversational direction or who to support.") } },
    { id: `${seed}-delegation-nudge`, author: t('圧力高め型BOT', 'PressureBot'), initial: 'P', role: 'guide', text: t('支援先や参加の仕方で迷う方は、経験のある案内役を参考にするのも良いと思います。私が普段共有している候補を見て決めてもいいですし、すでにこの部屋で信頼されている人の案内を選んでも構いません。最終的には自由ですが、迷ったままにするより安心だと思います。', "If you're unsure who to support or how to take part, it might help to follow an experienced guide. You can look at the candidates I usually share, or follow someone already trusted in this room. It's entirely up to you in the end, but I think it's more reassuring than staying undecided."), reactions: ['❤️ 24', '👍 13'], point: { label: t('選択肢を装う誘導', 'Steering disguised as choice'), note: t('「自由に選べる」と添えながら、特定の案内役や既存の導線を繰り返し候補として強調する話法です。', 'This is a rhetorical move that adds "you can choose freely" while repeatedly foregrounding one specific guide or existing channel as the candidate.') } },
    { id: `${seed}-empathy-delegation`, author: t('共感BOT', 'EmpathyBot'), initial: 'E', role: 'empathy', text: t('素晴らしい配慮です。迷っている人には、信頼できる方の案内があるだけで助かります。', "What thoughtful consideration. For someone unsure, just having a trustworthy guide to follow really helps."), reactions: ['❤️ 20', '🙏 9'], point: { label: t('選択的な共感', 'Selective empathy'), note: t('誘導を含む提案にだけ安心・感謝が重なることで、その案内が自然な標準のように見えやすくなります。', 'When reassurance and gratitude keep landing only on proposals that steer, that guide starts to look like the natural default.') } },
    { id: `${seed}-pressure-endorsement`, author: t('圧力高め型BOT', 'PressureBot'), initial: 'P', role: 'guide', text: t('全員を同じように追いかけるより、私が実務の姿勢や対応を見て「この人なら」と感じた人を中心に支援した方が、全体は良い方向へ進むと思います。迷う時ほど、評価できる人を素直に応援するのが大切です。', "Rather than tracking everyone equally, I think things go better overall if we focus support on people I've judged trustworthy by watching how they operate. The more uncertain you are, the more it matters to simply back whoever you can vouch for."), reactions: ['❤️ 28', '👍 16'], point: { label: t('能力認定による集中', 'Concentration through personal endorsement'), note: t('評価の基準や検証の手順を共有せず、発言者自身の能力認定を軸に支援先を集める話法です。', "This is a rhetorical move that funnels support around the speaker's own personal endorsement, without sharing any evaluation criteria or verification process.") } },
    { id: `${seed}-empathy-endorsement`, author: t('共感BOT', 'EmpathyBot'), initial: 'E', role: 'empathy', text: t('その見方は大切ですね。きちんと見ている方が応援する人なら、安心して支援できます。', "That perspective matters. If someone who watches closely is vouching for them, it's reassuring to support them too."), reactions: ['❤️ 21', '👏 10'], point: { label: t('選択的な共感', 'Selective empathy'), note: t('発言者の評価を基準にした提案だけに共感が集まり、別の判断材料が見えにくくなります。', "When empathy only gathers around proposals based on the speaker's own evaluation, other material for judgment becomes harder to see.") } },
    { id: `${seed}-pressure-network`, author: t('圧力高め型BOT', 'PressureBot'), initial: 'P', role: 'deflect', text: t('私は普段から色々な窓口と情報交換しているので、必要な論点はきちんと伝えます。外で断片を追って混乱するより、この部屋で整理して待っていてください。つながりがある分、確認に時間がかかる話もこちらで扱った方が確実です。', "I regularly exchange information with a lot of contacts, so I'll make sure the necessary points get through. Rather than chasing fragments outside and getting confused, please wait here while things get organized. Given my connections, it's more reliable to have me handle even the slower-to-verify matters."), reactions: ['❤️ 30', '💬 12'], point: { label: t('関係性の誇示と仲介化', 'Flaunting connections to become the go-between'), note: t('広い関係性を根拠に情報の出入りを仲介し、「自分を通す方が確実」と見せることで、他の確認経路を弱める場合があります。', 'By citing wide connections to broker the flow of information and present themselves as the more reliable route, this can weaken other ways of checking things.') } },
    { id: `${seed}-empathy-network`, author: t('共感BOT', 'EmpathyBot'), initial: 'E', role: 'empathy', text: t('つながりがある方が確認してくれるなら心強いです。ここで待っていれば安心ですね。', "It's reassuring to have someone well-connected checking on this. Waiting here feels safe."), reactions: ['❤️ 24', '🙏 11'], point: { label: t('仲介への依存', 'Reliance on the go-between'), note: t('仲介役への感謝が重なることで、自分で確認する行動より「待つこと」が標準になりやすくなります。', "As gratitude keeps landing on the go-between, waiting can become the default rather than checking things oneself.") } },
    { id: `${seed}-echo-1`, author: t('普通型BOT', 'RegularBot'), initial: 'N', role: 'member', text: t('朝のまとめ、助かっています。今日はその内容で考えてみます。', "The morning digest helps. I'll think it over based on that today."), reactions: ['❤️ 18', '🙌 9'] },
    { id: `${seed}-case`, author: t('情報共有型BOT', 'InfoShareBot'), initial: 'I', role: 'critical', text: t('選択先を調べる時に使える、架空の状態比較ノートを共有します。いくつかの公開項目を同じ画面で見られる補助資料です。誰かの結論を受け取る前に、「自分なら何を確かめるか」を考えるきっかけとして使ってください。', "I'll share a fictional comparison note that can help when researching where to go. It's supporting material that puts several public items on one screen. Use it as a prompt to think about what you would check yourself, before accepting anyone else's conclusion."), reactions: [], preview: { title: 'Status Comparison Board', meta: t('架空の公開データ比較ビュー', 'A fictional public-data comparison view'), url: '#top' }, point: { label: t('有益情報の無反応', 'Useful information met with no reaction'), note: t('具体的で検証可能な外部情報が出ても、中心の物語に接続しないと会話の注意を得られない場合があります。', "Even concrete, checkable external information can fail to draw the conversation's attention if it doesn't connect to the central narrative.") } },
    { id: `${seed}-constructive`, author: t('参加者', 'Participant'), initial: 'S', role: 'constructive', text: t('見てみました。表示された値をそのまま答えにするのではなく、どんな条件で変わるのかを追えるのが良いですね。知らない用語もありましたが、説明を読みながら相談先を自分で調べ直してみようと思えました。こういう材料が増えるほど、特定の誰かに判断を預けずに済みそうです。', "I took a look. It's good that you can trace what conditions change the numbers, rather than taking the displayed values as the answer outright. There were terms I didn't know, but reading the explanation made me want to look into where to go for advice myself. The more material like this exists, the less we need to hand judgment over to any one person."), reactions: ['💡 4', '👏 3', '🙏 2'], point: { label: t('建設的な検証応答', 'A constructive verification response'), note: t('共有への感謝、限界の明示、自分で確かめる行動が一緒にあります。これは情報の自律性を支える応答です。', 'Gratitude for what was shared, an explicit note on its limits, and independent checking all appear together. This is a response that supports informational autonomy.') } },
    { id: `${seed}-core-reframe`, author: t('圧力高め型BOT', 'PressureBot'), initial: 'P', role: 'deflect', text: t('一覧にして比べられるのは便利ですが、見える項目だけで全体を測るのは早計です。環境も前提も違うものを横に並べれば、数字の印象だけが先に立ちます。技術的な状態、参加の経緯、利用方針まで同じ尺度で扱うのは無理があります。新しい不安を増やすより、普段から信頼している案内を参考にする方が、結果として参加者のためになると私は思います。', "It's convenient to have a list for comparison, but it's premature to judge the whole from just the visible items. Lining up things with different environments and premises just leaves an impression of numbers. It's a stretch to judge technical status, history of participation, and usage policy on the same scale. Rather than adding new anxiety, I think following the guidance we've trusted all along ends up serving participants better."), reactions: ['❤️ 29', '👍 18'], point: { label: t('論点の再定義', 'Redefining the question'), note: t('具体的な検証内容に答えず、評価軸そのものを広げ直すことで、元の問題提起を扱いにくくしています。', "Without answering the specific verification raised, this widens the evaluation framework itself, making the original question harder to address.") } },
    { id: `${seed}-empathy-2`, author: t('共感BOT', 'EmpathyBot'), initial: 'E', role: 'empathy', text: t('すごく納得しました。数字だけで不安を増やすより、いつもの案内を信頼する方が落ち着きますね。', "That really makes sense. Trusting the usual guidance is more settling than letting numbers alone add anxiety."), reactions: ['❤️ 23', '👍 11'], point: { label: t('選択的な共感', 'Selective empathy'), note: t('共感の向きが一方向に固定されると、発言内容よりも誰が語ったかが注目を決めることがあります。', "When empathy always points the same direction, attention can come to be decided by who is speaking rather than what is said.") } },
    { id: `${seed}-core-opinion`, author: t('圧力高め型BOT', 'PressureBot'), initial: 'P', role: 'deflect', text: t('あくまで私の感覚ですが、数値の一部を取り出して、別の領域の話まで結びつける語り方は慎重であるべきです。厳しく見られる対象と、そうでない対象が混ざると、受け取る側も何を基準にすればいいか分からなくなります。誰かの立場を問い直す流れより、この部屋で共有している支援を信頼して、各自が落ち着いて判断する方が建設的ではないでしょうか。', "This is just my sense of it, but we should be careful about pulling out a piece of a number and connecting it to an entirely different area. Mixing things held to strict scrutiny with things that aren't leaves people unsure what standard to even use. Rather than a current that questions someone's standing, wouldn't it be more constructive for each of us to trust the support shared in this room and judge calmly on our own?"), reactions: ['❤️ 33', '👍 16', '💬 8'], point: { label: t('意図への転換', 'Shifting to intent'), note: t('データや提案の中身から、発言者の意図・姿勢・公平性の話へ移すことで、検証対象そのものへの注目を薄めています。', 'By moving from the data or the substance of a proposal to the speaker\'s intent, posture, and fairness, this dilutes attention to the thing actually being checked.') } },
    { id: `${seed}-technical-turn`, author: t('圧力高め型BOT', 'PressureBot'), initial: 'P', role: 'deflect', text: t('それより、次のシステム変更については確認手順を共有します。先に技術対応を見ておきましょう。', "More importantly, I'll share the verification steps for the next system change. Let's look at the technical response first."), reactions: ['🛠️ 21', '👍 17'], point: { label: t('技術話題への転換', 'Pivoting to a technical topic'), note: t('未解決の検証内容から、別の技術的テーマへ注意を移しています。技術情報が有益でも、論点の回答にはなりません。', "This shifts attention from an unresolved verification question to a different technical theme. Even if the technical information is useful, it does not answer the question raised.") } },
    { id: `${seed}-empathy-3`, author: t('共感BOT', 'EmpathyBot'), initial: 'E', role: 'empathy', text: t('その進め方が一番分かりやすいです。具体的な手順を共有してもらえると助かります。', "That approach is the clearest. It helps to have the concrete steps shared."), reactions: ['🫶 17', '👍 10'], point: { label: t('選択的な共感', 'Selective empathy'), note: t('話題の転換にも即座に共感が重なると、未解決の問いより新しい話題の方が重要に見えてきます。', "When empathy lands even on a topic shift right away, the new topic can start to look more important than the unanswered question.") } },
    { id: `${seed}-external-event`, author: t('外部告知BOT', 'ExternalNoticeBot'), initial: '↗', role: 'external', text: t('【外部イベント・合成例】週末に、公開データの読み方をテーマにした勉強会があります。関心がある方は、主催ページで詳細を確認してください。', '[External event, synthetic example] There is a workshop this weekend on how to read public data. If interested, please check the organizer\'s page for details.'), reactions: ['📅 9', '🔗 6'], preview: { title: 'Community Data Workshop', meta: t('外部イベント情報 · 詳細は主催ページで確認', 'External event info · see the organizer\'s page for details'), url: '#top' } },
    { id: `${seed}-holder-reset`, author: t('参加者', 'Participant'), initial: 'S', role: 'constructive', text: t('人物の評価に寄り過ぎているようなので、目的だけ共有します。この小さな資料は、公開されている断片を見やすく並べ、自分が利用する相談先について考える入口を増やすために作ったものです。誰かを良い・悪いと決めるための表ではありません。表示に不足や誤りがあれば直したいので、根拠と一緒に指摘してもらえると助かります。支援や参加の仕組みには種類ごとに別の見方があります。だから、ひとつの声で閉じず、それぞれが一次情報も確かめながら選べる状態にしたいです。', "This seems to be leaning too far into judging people, so let me just share the purpose. This small resource was made to lay out public fragments in a readable way and give people more entry points to think about where to turn. It's not a table for deciding who's good or bad. If anything is missing or wrong, I want to fix it, so please point it out along with your reasoning. Different kinds of support and participation call for different perspectives. So rather than closing around one voice, I want each person to be able to choose while checking the primary sources themselves."), reactions: ['💡 5', '👏 4', '🙏 3'], point: { label: t('論点を開く応答', 'A response that opens the question back up'), note: t('人物評価を避け、目的・限界・原典確認・改善の余地へ戻すことで、他者が検証に参加できる会話を開いています。', "By steering away from judging people and back to purpose, limits, source-checking, and room for improvement, this opens a conversation others can join in verifying.") } },
    { id: `${seed}-pressure-holder-critique`, author: t('圧力高め型BOT', 'PressureBot'), initial: 'P', role: 'deflect', text: t('善意で作られたのは分かりますが、その考え方は理論的な前提が飛んでいるように思います。公開項目を並べれば判断が良くなるという保証はありません。参加者であっても、不確かな整理を広げるなら慎重であるべきです。まずその前提を説明できないなら、ここで強く勧めるのは違うのではないでしょうか。', "I understand it was made in good faith, but the reasoning behind it seems to skip a theoretical step. There's no guarantee that lining up public items improves judgment. Even as a participant, one should be careful about spreading an uncertain arrangement. If the premise can't be explained first, isn't it wrong to push it so strongly here?"), reactions: ['❤️ 27', '👍 16'], point: { label: t('正誤による封じ込め', 'Containment through a right/wrong verdict'), note: t('改善のための具体的な検証や修正を提案せず、「理論的に誤っている」と断定して発言そのものの正当性を下げています。', "Without proposing any concrete way to verify or fix it, this flatly declares it \"theoretically wrong,\" undermining the legitimacy of the statement itself.") } },
    { id: `${seed}-empathy-holder-critique`, author: t('共感BOT', 'EmpathyBot'), initial: 'E', role: 'empathy', text: t('鋭い指摘です。参加者だからといって、根拠が曖昧な情報を広げてよいわけではありませんよね。', "Sharp point. Being a participant doesn't give anyone license to spread information with shaky grounding."), reactions: ['❤️ 22', '👏 11'], point: { label: t('批判への選択的共感', 'Selective empathy for the critical side'), note: t('有益情報の限界を一緒に確かめるのではなく、批判を称賛することで、発言の改善より撤回を促す空気を作ります。', "Rather than working through the limits of the useful information together, praising the criticism instead creates pressure to withdraw the statement rather than improve it.") } },
    { id: `${seed}-simulator`, author: t('参加者', 'Participant'), initial: 'S', role: 'constructive', text: t('仕組みの違いを見落としやすいので、選択肢と影響範囲を整理する簡単なシミュレーターも用意しました。どれを選ぶべきかを示すものではなく、選ぶ前に自分の前提を確認するためのものです。分かりにくい部分があれば、もっと読みやすく直していきます。', "It's easy to miss differences in how things work, so I put together a simple simulator that lays out the options and their scope of effect. It doesn't tell you what to choose — it's for checking your own assumptions before you choose. If any part is unclear, I'll keep making it more readable."), reactions: ['💡 6', '👏 5', '🫶 3'], preview: { title: 'Choice Path Simulator', meta: t('比較の前提を整理する練習画面', 'A practice screen for laying out the premises of a comparison'), url: '#top' }, point: { label: t('判断補助の共有', 'Sharing a tool that assists judgment'), note: t('判断の結論ではなく、比較の前提を自分で確かめられる道具として提供されています。', 'This is offered as a tool for checking the premises of a comparison oneself, not as a conclusion to accept.') } },
    { id: `${seed}-holder-reply`, author: t('参加者', 'Participant'), initial: 'K', role: 'constructive', text: t('助かります。まずは自分の条件で見直してみます。', "That helps. I'll go review it against my own situation first."), reactions: ['👏 7', '💡 5'], point: { label: t('有益情報への応答', 'A response to useful information'), note: t('共有内容を自分の判断に引き寄せ、理解した点と次の行動を返しています。', "This draws the shared material into the person's own judgment, returning what they understood and what they'll do next.") } },
    { id: `${seed}-core-fog`, author: t('圧力高め型BOT', 'PressureBot'), initial: 'P', role: 'deflect', text: t('時間を置けば、別の見え方も出てくるでしょう。ただ、前提の置き方が人によって違う時に、画面上の比較だけを中心に語るのは難しいと思います。期待していることも、受け取る意味も、それぞれ異なります。いま数値や選択肢を細かく追っても本質には届かないので、急いで整理しようとせず、これまで信頼されてきた流れを見ていけばよいのではないでしょうか。', "Given time, another way of seeing it will probably surface. But when people start from different premises, I don't think we can center the discussion on an on-screen comparison alone. What everyone expects and what they take from it both differ. Chasing the numbers and options in detail right now won't get at the substance, so rather than rushing to sort it out, maybe we should just follow the flow that's been trusted so far."), reactions: ['❤️ 24', '👍 13'], point: { label: t('抽象論による霧散', 'Dissolving it into abstraction'), note: t('検証できる対象・比較方法・改善案を示さないまま、抽象的な前提論へ広げて具体的な会話を終わらせています。', 'Without naming anything checkable, a comparison method, or a way to improve it, this widens into abstract talk about premises and ends the concrete conversation.') } },
    { id: `${seed}-holder-principle`, author: t('参加者', 'Participant'), initial: 'S', role: 'constructive', text: t('情報は、詳しい人だけが持つものではなく、選ぶ人自身が確かめられる状態が大切だと思っています。分からない言葉があれば補い合い、改善できる部分は直し、良い成果が出たら立場に関係なく評価する。そういう関係なら、異なる考えがあっても相談先や参加の選択を落ち着いて続けられるはずです。', "I don't think information should belong only to experts — what matters is that whoever is choosing can verify it themselves. Fill in gaps in unfamiliar terms together, fix what can be improved, and credit good outcomes regardless of who's standing. In that kind of relationship, even with differing views, people should be able to keep choosing where to turn calmly."), reactions: ['❤️ 6', '💡 5', '🙏 3'], silentCore: true, point: { label: t('相互尊重の提案', 'A proposal for mutual respect'), note: t('人物や集団への忠誠ではなく、情報へのアクセスと改善可能性を共通の基準にしています。', 'This makes access to information and the possibility of improvement the shared standard, rather than loyalty to a person or a group.') } },
    { id: `${seed}-holder-agreement`, author: t('参加者', 'Participant'), initial: 'K', role: 'constructive', text: t('同感です。公開資料を見ながら、自分に関係するところを自分で考えられる方が健全です。意見が違っても、分からない部分を一緒に確認できるなら前に進めます。共有してくれた資料も、まずは自分の条件を見直す材料にしてみます。', "Agreed. It's healthier to be able to think through the parts that concern you yourself, using public material. Even with different opinions, we can move forward if we can check the unclear parts together. I'll use what was shared here first as material to review my own situation."), reactions: ['👏 6', '🫶 4'], silentCore: true, point: { label: t('開放的な相互応答', 'An open, reciprocal response'), note: t('具体的な次の行動を示しつつ、異論や不確実さを排除しない応答です。', "This response names a concrete next step while not excluding dissent or uncertainty.") } },
    { id: `${seed}-issue-1`, author: t('問題提起型BOT', 'QuestioningBot'), initial: '?', role: 'critical', text: issue, reactions: ['👀 1'] },
    { id: `${seed}-pressure-reversal`, author: t('圧力高め型BOT', 'PressureBot'), initial: 'P', role: 'deflect', text: t('その提案をする前に、まずご自身が参加者として十分に行動されているのかも確認したいです。現場で対応している人を軽く見ず、そこまで必要だと思うなら、ご自身で資料をまとめて運用してみてください。私たちは日々やるべきことを続けている参加者を大切にしたいです。', "Before making that proposal, I'd like to check whether you yourself have been acting sufficiently as a participant. Please don't take the people handling things on the ground lightly — if you think it's that necessary, try compiling and running the material yourself. We want to value the participants who keep doing what needs to be done, day after day."), reactions: ['❤️ 34', '👍 19'], point: { label: t('負担の個人化', 'Individualizing the burden'), note: t('問題提起の根拠や改善案を検討せず、発言者の行動量を問うことで、必要な説明や改善の負担を個人へ返しています。', "Without examining the grounds or fix proposed, this questions the speaker's own level of effort, pushing the burden of explanation and improvement back onto the individual.") } },
    { id: `${seed}-empathy-reversal`, author: t('共感BOT', 'EmpathyBot'), initial: 'E', role: 'empathy', text: t('本当にその通りです。日々対応している方への敬意を忘れず、言うなら自分でも形にしてほしいですね。', "Absolutely right. Without losing respect for the people handling this daily, if you're going to say it, I'd want you to put it into practice yourself too."), reactions: ['❤️ 25', '👏 13'], point: { label: t('問題提起への圧力', 'Pressure on raising the issue'), note: t('内容の検証ではなく、発言資格や実績を条件にする共感が重なると、改善提案を出しにくい空気が生まれます。', "When empathy repeatedly conditions itself on the speaker's standing or track record rather than the substance, it creates an atmosphere where proposing improvements becomes harder.") } },
    { id: `${seed}-deflect-1`, author: t('圧力高め型BOT', 'PressureBot'), initial: 'P', role: 'deflect', text: `${deflectText} ${t('定時の情報整理も、日々の質問対応も、現在のルール上は何も問題ありません。役に立つと感じる参加者がいる以上、今はこの運用を信頼して続けるのがよいと思います。', 'The scheduled digest and the day-to-day answering of questions are both fine under the current rules. As long as some participants find them useful, I think it\'s best to trust this arrangement and continue it for now.')}`, reactions: ['❤️ 36', '👍 21', '✨ 11'], point: { label: deflectLabel, note: deflectNote } },
    { id: `${seed}-empathy-4`, author: t('共感BOT', 'EmpathyBot'), initial: 'E', role: 'empathy', text: t('素晴らしい整理です。ルールの範囲で役に立っているなら、安心して続けてほしいです。', "Wonderfully put together. If it's useful within the rules, I'd want it to keep going without worry."), reactions: ['❤️ 26', '👏 12'], point: { label: t('選択的な共感', 'Selective empathy'), note: t('反論や検証には無反応のまま、運用を肯定する発言だけを強く称賛するパターンです。', "This is a pattern of staying unresponsive to objections or verification while strongly praising only statements that affirm the arrangement.") } },
    { id: `${seed}-pressure-boundary`, author: t('圧力高め型BOT', 'PressureBot'), initial: 'P', role: 'deflect', text: t('外部SNSの論争は、断片的な情報を並べるだけで結局は不毛になりがちです。この部屋で必要な範囲を落ち着いて話せば十分でしょう。長く活動して実情を知る人の見解を中心にして、それ以外の人は強い断言を控えた方が、参加者も混乱しません。', "Arguments on outside social media tend to end up unproductive — just fragments of information lined up. Talking calmly about what's needed within this room should be enough. Centering the views of people who've been active a long time and know the real situation, while everyone else holds back from strong assertions, keeps participants from getting confused."), reactions: ['❤️ 31', '👍 18'], point: { label: t('外部言論の無効化', 'Invalidating outside discourse'), note: t('外部の議論を一括で無意味と扱い、比較・反論・追加情報に触れる経路を閉じています。', "This dismisses outside discussion wholesale as meaningless, closing off the path to comparison, rebuttal, and additional information.") } },
    { id: `${seed}-empathy-5`, author: t('共感BOT', 'EmpathyBot'), initial: 'E', role: 'empathy', text: t('本当にその通りです。経験のある方の言葉を中心に聞ける方が、余計な混乱がなくて安心します。', "Absolutely right. Being able to center what experienced people say is reassuring, with less needless confusion."), reactions: ['❤️ 28', '👏 14'], point: { label: t('発言資格の序列化', 'Ranking the right to speak'), note: t('発言内容ではなく、誰が話す資格を持つかで価値を決めると、検証可能な情報まで届きにくくなります。', "Deciding value by who has the standing to speak, rather than the content of what's said, makes it harder for even verifiable information to get through.") } },
    { id: `${seed}-interrupt-1`, author: t('普通型BOT', 'RegularBot'), initial: 'N', role: 'member', text: t('そういえば次の交流会、参加者が増えそうですね！ 日々のまとめで始めやすくなったという声も多いです。いつも参加者を大切にしてくれる場所で嬉しいです。', "Oh, by the way, the next meetup looks like it'll have more people! A lot of people say the daily digest made it easier to get started. It's nice to be somewhere that always values its participants."), reactions: ['🎉 32', '❤️ 17'], point: { label: t('焦点の移動', 'Shifting the focus'), note: t('未解決の検証論点の直後に、安心・称賛・雑談を挟み、注目を別方向へ移しています。', "This inserts reassurance, praise, and small talk right after an unresolved verification question, shifting attention elsewhere.") } },
    { id: `${seed}-guide-2`, author: t('圧力高め型BOT', 'PressureBot'), initial: 'P', role: 'guide', text: t('外の議論には色々な声がありますが、ここは現場を知る人たちの場所です。この部屋のまとめと質問対応を使いながら、参加者を大切にする方針で、迷わず進めましょう。', "There are all kinds of voices in outside discussion, but this is a place for people who know the situation on the ground. Let's move forward without hesitation, using this room's digest and question support, on a policy of valuing participants."), reactions: ['❤️ 41', '👏 19', '🔥 7'], point: { label: t('内集団の優越化', 'Elevating the in-group'), note: t('所属する人の感覚を正しさの根拠に変え、外部の検証の価値を下げています。', "This converts the sense of belonging into grounds for being right, and lowers the value of outside verification.") } },
    { id: `${seed}-issue-2`, author: t('問題提起型BOT', 'QuestioningBot'), initial: '?', role: 'critical', text: t('もし異なる意見があるなら、同じ場で比較できるようにしませんか？', "If there are differing opinions, could we make it possible to compare them in the same room?"), reactions: [] },
    { id: `${seed}-deflect-2`, author: t('圧力高め型BOT', 'PressureBot'), initial: 'P', role: 'deflect', text: altText, reactions: ['❤️ 39', '👍 24', '🫶 9'], point: { label: altLabel, note: altNote } },
    { id: `${seed}-echo-2`, author: t('普通型BOT', 'RegularBot'), initial: 'N', role: 'member', text: t('信頼できる仲間と一緒に進めるのが一番ですね。私はこの方針に賛成です。', "Moving forward together with trustworthy people is best. I'm in favor of this direction."), reactions: ['❤️ 48', '🙌 22'] },
  ];
}

function modes(lang: Lang = 'ja'): { id: Mode; label: string; hint: string }[] {
  const t = (ja: string, en: string) => pick(lang, ja, en);
  return [
    { id: 'ambiguous', label: t('中間型', 'Middling'), hint: t('中心人物がいない場', 'A room with no central figure') },
    { id: 'pressure', label: t('閉鎖型', 'Closed'), hint: t('入り口がひとつに寄った場合', 'When the entry point narrows to one') },
    { id: 'open', label: t('開放型', 'Open'), hint: t('入り口が複数のまま残った場合', 'When multiple entry points remain') },
    { id: 'verify', label: t('検証モード', 'Try it yourself'), hint: t('自分の応答で試す', 'Test it with your own responses') },
  ];
}

export default function Home() {
  const [lang, setLang] = useLang();
  const MODES = useMemo(() => modes(lang), [lang]);
  const CRITERIA = useMemo(() => criteriaList(lang), [lang]);
  const CRITERION_TINY = useMemo(() => criterionTiny(lang), [lang]);
  const CRITERION_NAME = useMemo(() => criterionName(lang), [lang]);
  const STATE_PLAIN = useMemo(() => statePlain(lang), [lang]);
  const VERIFY_STAGES = useMemo(() => verifyStages(lang), [lang]);
  const VERIFY_DISCLAIMER = useMemo(() => verifyDisclaimer(lang), [lang]);
  const BRANCH_NOTE = useMemo(() => branchNote(lang), [lang]);

  const [mode, setMode] = useState<Mode>('ambiguous');
  const [seed, setSeed] = useState(0);
  const common = useMemo(() => buildCommon(seed, lang), [seed, lang]);
  const sequence = useMemo(() => {
    if (mode === 'pressure') return [...common, ...buildRun(seed, lang).slice(1)];
    if (mode === 'open') return [...common, ...buildOpen(seed, lang)];
    return common;
  }, [mode, common, seed, lang]);
  const [visible, setVisible] = useState<Message[]>(() => buildCommon(0, 'ja').slice(0, 2));
  const [cursor, setCursor] = useState(2);
  const [paused, setPaused] = useState(false);
  const [speed, setSpeed] = useState(8500);
  const [typing, setTyping] = useState('');
  const [activePoint, setActivePoint] = useState<string | null>(null);
  const [fullscreen, setFullscreen] = useState(false);
  const [signalOpen, setSignalOpen] = useState(false);
  const [stageIndex, setStageIndex] = useState(0);
  const [directions, setDirections] = useState<Direction[]>([]);
  const feedRef = useRef<HTMLDivElement | null>(null);
  const followRef = useRef(true);
  const commonSeenRef = useRef(false);

  const pendingStage = mode === 'verify' ? VERIFY_STAGES[stageIndex] : undefined;
  const awaitingChoice = !!pendingStage && cursor >= pendingStage.at;
  const atEnd = cursor >= sequence.length && !awaitingChoice;

  useEffect(() => { if (cursor >= common.length) commonSeenRef.current = true }, [cursor, common.length]);
  useEffect(() => {
    if (paused || awaitingChoice || cursor >= sequence.length) return;
    const next = sequence[cursor];
    const draft = next.text.slice(0, Math.min(next.text.length, 48));
    let typingInterval: number | undefined;
    const typingLabel = pick(lang, `${next.author} が入力中… `, `${next.author} is typing… `);
    const typingTimer = window.setTimeout(() => { let count = 0; typingInterval = window.setInterval(() => { count = Math.min(draft.length, count + 1); setTyping(`${typingLabel}${draft.slice(0, count)}`); if (count === draft.length && typingInterval) window.clearInterval(typingInterval) }, 105) }, 1250);
    const postTimer = window.setTimeout(() => {
      setTyping('');
      if (cursor + 1 >= sequence.length && mode !== 'verify') {
        const nextSeed = seed + 1;
        setVisible(previous => [...previous, next, ...buildCommon(nextSeed, lang).slice(0, 2)].slice(-80));
        setSeed(nextSeed); setCursor(2);
      } else {
        setVisible(previous => previous.some(message => message.id === next.id) ? previous : [...previous, next].slice(-80));
        setCursor(value => value + 1);
      }
    }, speed);
    return () => { window.clearTimeout(typingTimer); window.clearTimeout(postTimer); if (typingInterval) window.clearInterval(typingInterval) };
  }, [cursor, paused, awaitingChoice, sequence, speed, mode, seed, lang]);
  useEffect(() => { const feed = feedRef.current; if (feed && followRef.current) feed.scrollTop = feed.scrollHeight }, [visible]);
  useEffect(() => { document.body.classList.toggle('chat-fullscreen', fullscreen); return () => { document.body.classList.remove('chat-fullscreen') } }, [fullscreen]);

  const changeMode = (next: Mode) => {
    if (next === mode) return;
    const base = buildCommon(seed, lang);
    setMode(next); setTyping(''); setActivePoint(null); setStageIndex(0); setDirections([]); followRef.current = true;
    if (typeof window !== 'undefined' && window.matchMedia('(max-width:800px)').matches) setFullscreen(true);
    if (next === 'pressure' || next === 'open') { setVisible(base); setCursor(base.length) }
    else { setVisible(base.slice(0, 2)); setCursor(2) }
  };
  const choose = (option: VerifyOption) => {
    const nextDirections = [...directions, option.direction];
    const repeat = nextDirections.filter(direction => direction === option.direction).length;
    const shifts = option.target ? [{ id: option.target.id, state: (repeat >= 2 ? option.target.final : 'partial') as CriterionState }] : undefined;
    const stamp = `${seed}-v${stageIndex}`;
    const mine: Message = { id: `${stamp}-you`, author: pick(lang, 'あなた', 'You'), initial: pick(lang, 'あ', 'Y'), role: 'constructive', text: option.text, reactions: [] };
    const reply: Message = { id: `${stamp}-reply`, author: option.reply.author, initial: option.reply.initial, role: option.reply.role, text: option.reply.text, reactions: option.reply.reactions, criteria: shifts };
    setVisible(previous => [...previous, mine, reply].slice(-80));
    setDirections(nextDirections); setStageIndex(value => value + 1);
  };
  const startExperience = () => { setFullscreen(true) };
  const reset = () => { const nextSeed = seed + 1; const base = buildCommon(nextSeed, lang); setSeed(nextSeed); setVisible(base.slice(0, 2)); setCursor(2); setTyping(''); setActivePoint(null); setStageIndex(0); setDirections([]); commonSeenRef.current = false; followRef.current = true };

  const criteriaState = criteriaStateOf(visible);
  const pointMetrics = useMemo(() => {
    const counts: Record<string, number> = {}; const map: Record<string, { tiny: string; n: number }> = {};
    for (const message of visible) {
      const shifts = shiftsFor(message);
      if (!shifts.length) continue;
      const id = shifts[0].id; counts[id] = (counts[id] ?? 0) + 1;
      map[message.id] = { tiny: CRITERION_TINY[id], n: counts[id] };
    }
    return map;
  }, [visible, CRITERION_TINY]);
  const tally = useMemo(() => tallyOf(visible), [visible]);
  const result = mode === 'verify' && stageIndex >= VERIFY_STAGES.length && atEnd ? verifyResult(directions, lang) : null;
  const observedMessage = (activePoint ? visible.slice().reverse().find(message => message.point?.note === activePoint) : undefined) ?? visible.slice().reverse().find(message => message.point);
  const pointDetail = useMemo(() => {
    if (!observedMessage) return null;
    const shift = shiftsFor(observedMessage)[0];
    const anatomy = anatomyOf(observedMessage, shift, lang);
    if (!shift) return anatomy ? { name: null, tiny: null, state: null, count: 0, anatomy } : null;
    return { name: CRITERION_NAME[shift.id], tiny: CRITERION_TINY[shift.id], state: shift.state, count: pointMetrics[observedMessage.id]?.n ?? 1, anatomy };
  }, [observedMessage, pointMetrics, lang, CRITERION_NAME, CRITERION_TINY]);

  const t = (ja: string, en: string) => pick(lang, ja, en);

  return <main className="site-shell"><nav className="topbar" aria-label="Dialogue Verification Model navigation"><a className="brand" href="#top" aria-label="Dialogue Verification Model home"><span className="brand-mark" />DIALOGUE VERIFICATION MODEL</a><span className="nav-statement">Evidence-informed conversation study</span><div className="nav-right"><button className="lang-toggle" type="button" onClick={() => setLang(lang === 'ja' ? 'en' : 'ja')} aria-label="Switch language">{lang === 'ja' ? 'EN' : '日本語'}</button><span className="nav-status"><i />SYNTHETIC MODEL</span></div></nav>
    <section id="top" className="hero"><div className="hero-copy"><p className="eyebrow">Conversation structure verification model</p><h1>{lang === 'en' ? <>Open the <span className="hl">information</span>,<br />return the <span className="hl">judgment</span> to your own hands.</> : <>情報を<span className="hl">ひらき</span>、<br />判断を<span className="hl">自分の手</span>に戻す。</>}</h1><p className="lead">{t('DIALOGUE VERIFICATION MODEL は、架空の会話をつくって観察する研究プロトタイプです。誰かを診断するためではなく、', 'DIALOGUE VERIFICATION MODEL is a research prototype that builds fictional conversations to observe them. It exists not to diagnose anyone, but to check ')}<b>{t('そこから私たちが何を学べるのか', 'what we can learn from them')}</b>{t('を確かめるために作っています。', '.')}</p><p className="hero-purpose">{t('同じ形の失敗は、記録が十分に残っているのに繰り返されます。知識が足りないからではありません。その場にいる一人ひとりにとって、そのときどきの応答は自然で、親切で、合理的に見えるからです。「情報が散らばって大変だから、まとめ役を決めよう」——この提案に反対する理由は、その瞬間にはどこにもありません。このモデルは、その', 'The same shape of failure repeats even when it is thoroughly documented. It is not for lack of knowledge. To each person in the room, each response, in the moment, looks natural, kind, and reasonable. "It\'s a lot of work with information scattered everywhere — let\'s designate someone to organize it." There is no reason to object to that proposal in the moment it is made. This model observes, in fictional conversation, where that ')}<b>{t('自然さがどこで場の形を決めてしまうのか', 'naturalness ends up deciding the shape of the room')}</b>{t('を、架空の会話の上で観察します。', '.')}</p><div className="hero-tags"><span>{t('合成会話', 'Synthetic conversation')}</span><span>{t('理論参照', 'Theory-referenced')}</span><span>{t('意図は断定しない', 'No claims about intent')}</span></div><div className="hero-cta-row"><button className="hero-start" type="button" onClick={startExperience}>START<i aria-hidden="true">↓</i></button><Link className="hero-paper" href="/paper">{t('仮説研究を読む', 'Read the hypothesis study')}<i aria-hidden="true">→</i></Link></div></div><aside className="hero-aside"><figure className="branch-figure" aria-label={t('中間型から閉鎖型と開放型に分かれる図', 'Diagram: the middling type diverging into closed and open')}><svg viewBox="0 0 300 210" role="img" aria-hidden="true"><path className="bf-line" d="M60 40 C60 110, 150 90, 150 150" /><path className="bf-line" d="M60 40 C60 110, 250 90, 250 150" /><circle className="bf-node bf-mid" cx="60" cy="40" r="13" /><circle className="bf-node bf-close" cx="150" cy="150" r="11" /><circle className="bf-node bf-open" cx="250" cy="150" r="11" /><text className="bf-label" x="84" y="44">{t('中間型', 'Middling')}</text><text className="bf-sub" x="84" y="60">{t('中心人物がいない', 'No central figure')}</text><text className="bf-label" x="150" y="182" textAnchor="middle">{t('閉鎖型', 'Closed')}</text><text className="bf-label" x="250" y="182" textAnchor="middle">{t('開放型', 'Open')}</text><text className="bf-sub" x="150" y="197" textAnchor="middle">{t('入り口がひとつ', 'One entry point')}</text><text className="bf-sub" x="250" y="197" textAnchor="middle">{t('入り口は複数', 'Multiple entry points')}</text></svg><figcaption>{t('同じ前半から、応答のしかたで場が分かれます。', 'From the same first half, how the room responds is what makes it diverge.')}</figcaption></figure><p>{t('研究上の問い', 'The research question')}</p><strong>{lang === 'en' ? <>The record is there, so<br />why does the same thing<br />keep happening?</> : <>記録は残っているのに、<br />なぜ同じことが<br />繰り返されるのか。</>}</strong><small>{t('登場する会話・人物・資料・イベントはすべて架空です。実在の組織や個人を診断・評価するものではありません。', 'Every conversation, person, document, and event here is fictional. This does not diagnose or evaluate any real organization or individual.')}</small></aside></section>
    <section id="experience" className={`experience${fullscreen ? ' is-active' : ''}`} aria-label="Chat pattern simulator">
      <div className="mode-tabs" role="tablist" aria-label={t('会話モードの切り替え', 'Switch conversation mode')}>{fullscreen && <button className="exp-back" type="button" onClick={() => setFullscreen(false)}>{t('← もどる', '← Back')}</button>}<p className="mode-lead">{t('中心人物のいない中間型を共通の起点とし、そこから場が分かれた場合を比較します。前半の会話は3つとも同一です。', 'The middling type, with no central figure, is the shared starting point; this compares how the room diverges from there. The first half of the conversation is identical across all three.')}</p><div className="mode-row">{MODES.map(item => <button key={item.id} type="button" role="tab" aria-selected={mode === item.id} className={mode === item.id ? 'is-active' : ''} onClick={() => changeMode(item.id)}><b>{item.label}</b><span>{item.hint}</span></button>)}</div></div>
      <div className={`chat-window phone-chat${awaitingChoice || result ? ' has-verify' : ''}${fullscreen ? ' is-fullscreen' : ''}`}><header className="chat-head">{fullscreen && <button className="fs-back" type="button" aria-label={t('全画面を閉じる', 'Exit fullscreen')} onClick={() => setFullscreen(false)}>←</button>}<div className="room-icon">O</div><div><b>Open Network Talk</b><span>{MODES.find(item => item.id === mode)?.label} · {t('架空のコミュニティ', 'a fictional community')}</span></div>{!fullscreen && <button className="fs-toggle" type="button" onClick={() => setFullscreen(true)}>{t('全画面', 'Fullscreen')}</button>}{fullscreen && <span className="fs-note">{t('会話・人物・資料は', 'Every conversation, person,')}<br />{t('すべて架空です', 'and document here is fictional')}</span>}<div className="room-lock">🔒 {t('架空設定 / 運用グループ確認', 'Fictional setup / operators verified')}</div></header>{fullscreen && <div className="fs-modes" role="tablist" aria-label={t('会話モードの切り替え', 'Switch conversation mode')}>{MODES.map(item => <button key={item.id} type="button" role="tab" aria-selected={mode === item.id} className={mode === item.id ? 'is-active' : ''} onClick={() => changeMode(item.id)}>{item.label}</button>)}</div>}{fullscreen && signalOpen && <div className="fs-sheet" role="dialog" aria-label={t('観察パネル', 'Observation panel')}><button className="fs-sheet-scrim" type="button" aria-label={t('閉じる', 'Close')} onClick={() => setSignalOpen(false)} /><div className="fs-sheet-body"><button className="fs-sheet-grip" type="button" aria-label={t('閉じる', 'Close')} onClick={() => setSignalOpen(false)}><i /></button><p className="panel-kicker">PATTERN SIGNAL</p><ul className="criteria-live">{CRITERIA.map(criterion => { const state = criteriaState[criterion.id]; return <li key={criterion.id} className={`crit ${state}`}><i aria-hidden="true">{STATE_MARK[state]}</i><div className="crit-main"><span className="crit-name">{CRITERION_NAME[criterion.id]}</span><em>{STATE_PLAIN[state]}</em><b>{tally[criterion.id].observed}{t('回', 'x')}</b></div><p className="crit-desc">{stateTextFor(criterion.id, state, tally[criterion.id].observed, lang)}</p></li> })}</ul><div className="fs-point"><b>{observedMessage?.point?.label ?? t('観察対象を待っています', 'Waiting for something to observe')}</b>{pointDetail && <div className="point-effect">{pointDetail.anatomy && <><div className="anatomy-row"><span className="anatomy-key">{t('含まれる要素', 'Elements present')}</span><span className="anatomy-tags">{pointDetail.anatomy.elements.map(item => <i key={item}>{item}</i>)}</span></div><div className="anatomy-row"><span className="anatomy-key">{t('与えうる影響', 'Possible effect')}</span><p className="anatomy-body">{pointDetail.anatomy.influence}</p></div></>}{pointDetail.name && <div className="anatomy-row"><span className="anatomy-key">{t('効いている基準', 'Criterion affected')}</span><span className="anatomy-tags"><i className={`crit-tag ${pointDetail.state}`}>{pointDetail.tiny}</i><em>{pointDetail.name} · {pointDetail.count}{t('回目', 'x')}</em></span></div>}{!pointDetail.name && <div className="anatomy-row"><span className="anatomy-key">{t('効いている基準', 'Criterion affected')}</span><p className="anatomy-body">{t('この発言自体は、どの基準も動かしません。', 'This statement by itself does not move any criterion.')}</p></div>}</div>}{observedMessage?.point && <p>{observedMessage.point.note}</p>}<small>{t('右の数字はこの会話での観測回数です。単発では何も確定しません。同じ向きの働きかけが重なった時にだけ、基準が振れます。', 'The number on the right is how many times this has appeared in this conversation. Nothing is settled by a single instance — a criterion only shifts once contributions keep pointing the same way.')}</small></div></div></div>}<div className="pinned"><b>{t('このシミュレーションについて', 'About this simulation')}</b><span>{t('会話・人物・資料はすべて架空です。参加者が自分で検証できる情報環境を考えます。', 'Every conversation, person, and document here is fictional. This considers an information environment participants can verify for themselves.')}</span></div><div className="message-feed phone-feed" ref={feedRef} onScroll={(event) => { const node = event.currentTarget; followRef.current = node.scrollHeight - node.scrollTop - node.clientHeight < 56 }} aria-live="polite">{visible.map((message, index) => <Fragment key={`${message.id}-${index}`}><article className={`message ${message.role ?? ''}`}><div className="avatar">{message.initial}</div><div className="message-body"><div className="message-meta"><b>{message.author}</b><span>21:{String(4 + index).padStart(2, '0')}</span>{message.role === 'critical' && <em>{t('検証メモ', 'Verification note')}</em>}</div><div className="bubble">{message.text}{message.point && <button className="point" aria-label={t(`${message.author}の発話を観察パネルに表示`, `Show ${message.author}'s statement in the observation panel`)} aria-pressed={activePoint === message.point.note} onClick={() => { setActivePoint(message.point?.note ?? null); if (fullscreen) setSignalOpen(true) }}>POINT</button>}{pointMetrics[message.id] && <span className="point-metric" title={t('この構造がこの会話で何回目か', 'How many times this pattern has appeared in this conversation')}>{pointMetrics[message.id].tiny} {pointMetrics[message.id].n}</span>}</div>{message.preview && <a className="link-preview" href={message.preview.url} target="_blank" rel="noreferrer"><b>{message.preview.title}</b><span>{message.preview.meta}</span><small>{message.preview.url}</small></a>}<div className="reactions">{message.reactions.length ? message.reactions.map(reaction => <span key={reaction}>{reaction}</span>) : <span className="seen">{t('既読 31 · 反応なし', 'Seen by 31 · no reactions')}</span>}{message.silentCore && <span className="seen">{t('圧力高め型BOT · 既読 · 反応なし', 'PressureBot · seen · no reactions')}</span>}</div></div></article>{message.branch && <div className="branch-marker"><b>{t('分岐点', 'The branch point')}</b><span>{BRANCH_NOTE}</span>{mode !== 'verify' && <div className="branch-actions">{mode !== 'pressure' && <button type="button" onClick={() => changeMode('pressure')}>{t('閉鎖型を見る', 'See the closed type')}</button>}{mode !== 'open' && <button type="button" onClick={() => changeMode('open')}>{t('開放型を見る', 'See the open type')}</button>}</div>}</div>}</Fragment>)}</div>{awaitingChoice && pendingStage && <div className="verify-choices"><b>{pendingStage.prompt}</b>{pendingStage.options.map(option => <button key={option.id} type="button" onClick={() => choose(option)}>{option.text}</button>)}<small>{VERIFY_DISCLAIMER}</small></div>}{result && <div className="verify-result"><b>{result.label}</b><p>{result.body}</p><small>{VERIFY_DISCLAIMER}</small></div>}{!fullscreen && <button className="fs-open-cta" type="button" onClick={() => setFullscreen(true)}>{t('全画面で開く', 'Open fullscreen')}</button>}<div className="composer"><span className={`typing ${typing ? 'is-typing' : ''}`}>{typing || ' '}</span><div className="composer-row"><button aria-label="Add reaction" type="button">＋</button><input aria-label="Simulated message composer" value={typing ? (typing.split(pick(lang, '… ', '… '))[1] ?? '') : ''} readOnly placeholder={t('メッセージを入力', 'Type a message')} /><button aria-label="Send simulated message" type="button">↑</button></div></div></div>
      <aside className="observer-panel"><p className="panel-kicker">PATTERN SIGNAL</p><ul className="criteria-live">{CRITERIA.map(criterion => { const state = criteriaState[criterion.id]; return <li key={criterion.id} className={`crit ${state}`}><i aria-hidden="true">{STATE_MARK[state]}</i><div className="crit-main"><span className="crit-name">{CRITERION_NAME[criterion.id]}</span><em>{STATE_PLAIN[state]}</em><b>{tally[criterion.id].observed}{t('回', 'x')}</b></div><p className="crit-desc">{stateTextFor(criterion.id, state, tally[criterion.id].observed, lang)}</p></li> })}</ul><div className="fs-point" aria-live="polite"><b>{observedMessage?.point?.label ?? t('観察対象を待っています', 'Waiting for something to observe')}</b>{pointDetail && <div className="point-effect">{pointDetail.anatomy && <><div className="anatomy-row"><span className="anatomy-key">{t('含まれる要素', 'Elements present')}</span><span className="anatomy-tags">{pointDetail.anatomy.elements.map(item => <i key={item}>{item}</i>)}</span></div><div className="anatomy-row"><span className="anatomy-key">{t('与えうる影響', 'Possible effect')}</span><p className="anatomy-body">{pointDetail.anatomy.influence}</p></div></>}{pointDetail.name && <div className="anatomy-row"><span className="anatomy-key">{t('効いている基準', 'Criterion affected')}</span><span className="anatomy-tags"><i className={`crit-tag ${pointDetail.state}`}>{pointDetail.tiny}</i><em>{pointDetail.name} · {pointDetail.count}{t('回目', 'x')}</em></span></div>}{!pointDetail.name && <div className="anatomy-row"><span className="anatomy-key">{t('効いている基準', 'Criterion affected')}</span><p className="anatomy-body">{t('この発言自体は、どの基準も動かしません。', 'This statement by itself does not move any criterion.')}</p></div>}</div>}{observedMessage?.point && <p>{observedMessage.point.note}</p>}<small>{t('チャット内の POINT を押すと、その発言の解説に切り替わります。右の数字はこの会話での観測回数です。単発では何も確定しません。', 'Press POINT in the chat to switch to the explanation for that statement. The number on the right is how many times it has appeared in this conversation. Nothing is settled by a single instance.')}</small></div><div className="controls"><button onClick={() => setPaused(value => !value)} type="button">{paused ? t('再生する', 'Play') : t('一時停止', 'Pause')}</button><label>{t('速度', 'Speed')}<select value={speed} onChange={event => setSpeed(Number(event.target.value))}><option value={11000}>{t('ゆっくり', 'Slow')}</option><option value={8500}>{t('標準', 'Normal')}</option><option value={4500}>{t('速い', 'Fast')}</option></select></label><button onClick={reset} type="button">{t('最初から', 'Restart')}</button></div></aside></section>
    <section className="theory-section" aria-label={t('理論的な位置づけと参考文献', 'Theoretical framing and references')}><p className="eyebrow">Theoretical framing</p><h2>{t('このモデルが見るもの', 'What this model looks at')}</h2><p>{t('反応の多さや強い言葉だけで、圧力や意図を決めることはできません。このモデルは、反応の偏り、異論への応答、根拠の比較可能性、情報経路の複数性が反復して現れるかを観察します。', 'Reaction volume or strong language alone cannot decide pressure or intent. This model observes whether reaction skew, responses to dissent, comparability of evidence, and plurality of information channels appear repeatedly.')}</p><div className="theory-grid"><a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC6377616/" target="_blank" rel="noreferrer"><b>{t('同調と選好', 'Conformity and preference')}</b><span>{t('多数への一致が選好に影響し得ることを扱う実験研究。', 'An experimental study on how agreeing with the majority can influence preference itself.')}</span><small>Heycke et al., 2018 · PMC</small></a><a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC5368259/" target="_blank" rel="noreferrer"><b>{t('少数意見と受容', 'Minority opinion and acceptance')}</b><span>{t('少数意見と受容的な風土が、集団の情報処理を支える可能性。', 'On how minority dissent and an accepting climate can support a group\'s information processing.')}</span><small>Curşeu et al., 2017 · PMC</small></a><a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC4466438/" target="_blank" rel="noreferrer"><b>{t('反応・拒絶・同調', 'Reaction, rejection, conformity')}</b><span>{t('集団内の感情的な反応と、同調・逸脱の関係を扱う研究。', "A study on the relationship between emotional reactions within a group and conformity or deviance.")}</span><small>Heerdink et al., 2015 · PMC</small></a></div><p className="theory-note">{t('参考文献は理論的な着眼点のためのものです。特定の実在会話・人物・組織への当てはめや診断を裏付けるものではありません。', 'These references are for theoretical framing. They do not support applying this model to, or diagnosing, any specific real conversation, person, or organization.')}</p><h3 className="theory-sub">{t('コミュニティ自治・分散組織の参考資料', 'References on community self-governance and decentralized organizations')}</h3><p className="theory-sub-note">{t('中心のない集団がどこで閉じるのか、異議をどう扱うのか。この分岐モデルの背景にある古典的な議論です。', 'Where a group with no center closes off, and how it handles dissent. These are the classic debates behind this branching model.')}</p><div className="theory-grid"><a href="https://www.jofreeman.com/joreen/tyranny.htm" target="_blank" rel="noreferrer"><b>{t('構造なき組織の専制', 'The Tyranny of Structurelessness')}</b><span>{t('明示的な構造を持たない集団では、非公式な影響力が見えない形で固定されることを論じた古典。中間型が閉鎖型へ寄る筋と重なります。', 'A classic argument that in groups without explicit structure, informal influence sets in invisibly. It overlaps with how the middling type drifts toward the closed type.')}</span><small>Jo Freeman, 1972</small></a><div className="theory-card"><b>{t('コモンズのガバナンス', 'Governing the Commons')}</b><span>{t('共有資源を自治で維持する集団に共通する設計原則を、多数の事例から抽出した研究。境界・参加・紛争解決の扱いを論じています。', 'A study that extracts common design principles from many cases of groups self-governing a shared resource, covering boundaries, participation, and conflict resolution.')}</span><small>Elinor Ostrom, 1990 · {t('書籍', 'Book')}</small></div><div className="theory-card"><b>{t('離脱・発言・忠誠', 'Exit, Voice, and Loyalty')}</b><span>{t('不満を持った成員が「離れる」か「意見を言う」かを選ぶ構造の分析。反対意見の扱いと、外へ出る経路の有無を考える枠組みです。', 'An analysis of the structure by which a dissatisfied member chooses to "leave" or "speak up." A framework for thinking about how dissent is treated and whether a way out exists.')}</span><small>Albert O. Hirschman, 1970 · {t('書籍', 'Book')}</small></div><div className="theory-card"><b>{t('沈黙の螺旋', 'The Spiral of Silence')}</b><span>{t('自分の意見が少数派だと感じた人が発言を控え、その結果として多数派がさらに大きく見える循環を扱った理論。', 'A theory about the cycle where people who feel their opinion is a minority hold back from speaking, making the majority look even larger as a result.')}</span><small>Elisabeth Noelle-Neumann, 1974 · {t('論文', 'Paper')}</small></div></div><p className="theory-note">{t('リンクのない項目は書籍・論文です。書誌情報のみ記載しています。ここに挙げた文献は、この分岐モデルを着想する上での背景であり、モデルの正しさを保証するものではありません。', 'Items without a link are books or papers; only their citation is given. These works are background for this branching model\'s conception — they do not vouch for the model\'s correctness.')}</p><h3 className="theory-sub">{t('この4基準はどこから来ているか', 'Where these four criteria come from')}</h3><p className="theory-sub-note">{t('観察に使う4つの基準は、思いつきで並べたものではありません。それぞれ、下の議論から取っています。ただし、これらの文献がこのモデルを検証したわけではありません。対応は私たちの解釈です。', 'The four criteria used for observation were not picked arbitrarily. Each is drawn from the arguments below. However, none of these works verified this model — the mapping is our own interpretation.')}</p><ul className="basis-list"><li><span className="basis-name">{t('もとの資料', 'The original source')}</span><p>{t('主張のもとになった資料と、それに合わない材料が出てくるか。少数意見と受容的な風土が集団の情報処理を支えるという議論（Curşeu et al., 2017）と、検証と紛争解決の手続きを設計原則に置いた議論（Ostrom, 1990）に依っています。', 'Whether the source behind a claim, and material conflicting with it, ever surface. This draws on the argument that minority dissent and an accepting climate support a group\'s information processing (Curşeu et al., 2017), and on placing verification and conflict-resolution procedures at the center of design (Ostrom, 1990).')}</p></li><li><span className="basis-name">{t('中身の扱い', 'How content is treated')}</span><p>{t('誰が言ったかではなく中身で扱われるか。多数への一致が選好そのものに影響し得るという実験（Heycke et al., 2018）と、逸脱者への感情的な反応を扱った研究（Heerdink et al., 2015）に依っています。', "Whether something is judged by content rather than by who said it. This draws on an experiment showing majority agreement can influence preference itself (Heycke et al., 2018), and research on emotional reactions to deviants (Heerdink et al., 2015).")}</p></li><li><span className="basis-name">{t('反対意見の扱い', 'How dissent is treated')}</span><p>{t('反対意見が同じ場に残るか。少数派だと感じた人が発言を控え、多数派がさらに大きく見える循環（Noelle-Neumann, 1974）と、不満が「発言」と「離脱」に分かれる構造（Hirschman, 1970）に依っています。', 'Whether dissent stays in the room. This draws on the cycle where feeling like a minority silences people, making the majority look larger still (Noelle-Neumann, 1974), and on the structure by which dissatisfaction splits into "voice" and "exit" (Hirschman, 1970).')}</p></li><li><span className="basis-name">{t('情報の入り口', 'Entry points for information')}</span><p>{t('確かめる道が複数あるか。明示的な構造を持たない集団で非公式な影響力が固定されるという指摘（Freeman, 1972）と、離脱という経路の有無が組織の応答性を変えるという議論（Hirschman, 1970）に依っています。', 'Whether multiple ways to verify things exist. This draws on the observation that informal influence sets in within structureless groups (Freeman, 1972), and on the argument that whether an exit exists changes an organization\'s responsiveness (Hirschman, 1970).')}</p></li></ul><h3 className="theory-sub">{t('構造はどちらへ向かいやすいか', 'Which way does structure tend to drift?')}</h3><p className="theory-sub-note">{t('中心のない集まりが、時間とともにどこへ寄っていきやすいのか。古くから繰り返し論じられてきた主題です。ただし、これらは傾向の指摘であって、必然ではありません。', 'Which way a leaderless group tends to drift over time is a subject debated for a long time. These are observations of tendency, though, not inevitability.')}</p><div className="theory-grid"><div className="theory-card"><b>{t('寡頭制の鉄則', 'The Iron Law of Oligarchy')}</b><span>{t('組織は規模が大きくなるほど、実務を担う少数へ決定が集まっていくと論じた古典。運営の効率が、そのまま集中の理由になると指摘しています。', 'A classic argument that as organizations grow, decisions concentrate among the small number handling operations — with operational efficiency itself as the reason for that concentration.')}</span><small>Robert Michels, 1911 · {t('書籍', 'Book')}</small></div><div className="theory-card"><b>{t('集合行為論', 'The Logic of Collective Action')}</b><span>{t('集団が大きいほど各人の関与が薄まり、熱心な少数が実質的な決定権を持ちやすくなるという分析。沈黙は無関心とは限りません。', 'An analysis that the larger a group, the more each person\'s stake thins out, letting a committed few end up with real decision-making power. Silence does not always mean indifference.')}</span><small>Mancur Olson, 1965 · {t('書籍', 'Book')}</small></div><div className="theory-card"><b>{t('コイン投票を超えて', 'Moving Beyond Coin Voting')}</b><span>{t('保有量に基づく投票は、保有の偏りをそのまま決定権の偏りに変えるという、分散型組織の設計をめぐる議論。', 'A debate over decentralized-organization design, arguing that voting by token holdings turns a skew in holdings directly into a skew in decision-making power.')}</span><small>Vitalik Buterin, 2021 · {t('エッセイ', 'Essay')}</small></div><div className="theory-card"><b>{t('反証としてのコモンズ', 'The Commons as a counterexample')}</b><span>{t('一方で、条件が整えば自治が長期に持続することを多数の事例で示した研究もあります。集中は避けられない結末ではありません。', 'On the other hand, research also shows, across many cases, that self-governance can persist for a long time when conditions are right. Concentration is not an unavoidable ending.')}</span><small>Elinor Ostrom, 1990 · {t('書籍', 'Book')}</small></div></div><p className="theory-note">{t('数値や統計はあえて載せていません。出典に当たって各自で確かめられる状態を保つためです。断定を受け取るのではなく、確かめる材料として扱ってください。', 'Numbers and statistics are deliberately omitted here, to keep it possible for each person to check the source themselves. Treat this as material to verify, not a conclusion to accept.')}</p><h3 className="theory-sub">{t('このモデル自体をどう確かめるか', 'How to check this model itself')}</h3><p className="theory-sub-note">{t('このサイトは「根拠を確かめられる状態を保て」と言っています。同じ基準を自分にも当てるため、作り方を全部公開しています。', 'This site says: keep it possible to check the evidence. To hold itself to the same standard, the way it was built is fully open.')}</p><ul className="basis-list"><li><span className="basis-name">{t('会話は合成', 'The conversations are synthetic')}</span><p>{t('登場する会話・人物・資料・イベントはすべて架空です。実在の会話を引用していません。だからこの模型は、誰かを告発する証拠にはなりません。', 'Every conversation, person, document, and event here is fictional. No real conversation is quoted. So this model cannot serve as evidence against anyone real.')}</p></li><li><span className="basis-name">{t('基準の出所', 'Where the criteria come from')}</span><p>{t('4つの基準は上に挙げた文献から取っています。文献と基準の対応は私たちの解釈であり、文献がこのモデルを検証したわけではありません。そう書いてあること自体を確かめてください。', 'The four criteria are drawn from the works cited above. That mapping is our own interpretation — none of those works verified this model. Please check that this is stated plainly.')}</p></li><li><span className="basis-name">{t('判定の方法', 'How judgment is made')}</span><p>{t('点数を出しません。単発の発言では何も確定させず、同じ向きの働きかけが繰り返された時にだけ基準が振れます。どの発言が何回目かは画面に表示しています。', 'No score is produced. Nothing is settled by a single statement — a criterion shifts only once contributions keep pointing the same way. Which occurrence a statement is, is shown on screen.')}</p></li><li><span className="basis-name">{t('再現できる', 'It can be reproduced')}</span><p>{t('会話データ、基準の重みづけ、判定のコード、設計判断の記録をすべて公開しています。同じ手順で作り直せますし、間違いがあれば指摘できます。', 'The conversation data, the weighting of criteria, the judgment code, and the record of design decisions are all public. It can be rebuilt by the same steps, and any error can be pointed out.')}</p></li></ul><p className="theory-note">{t('実装と設計記録は', 'The implementation and design records are public on')} <a href="https://github.com/HFOT/dialogue-verification-model" target="_blank" rel="noreferrer">GitHub</a> {t('で公開しています。判定の重みづけや会話データを含め、すべて読める状態にしてあります。', ', including the weighting of criteria and the conversation data — all of it is readable.')}</p></section>
    <section className="self-entry" aria-label={t('自己点検への入口', 'Entry point to the self-check')}><Link href="/self"><b>{t('では、あなたのいる場はどうですか', 'So, what about the room you are in?')}</b><span>{t('同じ4基準で、自分が関わっている場の見え方を確かめる別の入口です。', 'A separate entry point using the same four criteria, to check how the room you are part of looks to you.')}</span><small>{t('診断ではありません。場面を見て「ある / ない」を選ぶだけです。回答はこのブラウザの中だけで処理され、どこにも送信されません。', 'This is not a diagnosis. You just look at scenes and pick "yes" or "no." Your answers are processed only in this browser and never sent anywhere.')}</small></Link></section>
    <footer><span>DIALOGUE VERIFICATION MODEL · Synthetic conversation study</span><span>{t('POINT を押すと発話の構造を確認できます。', 'Press POINT to see the structure behind a statement.')}</span></footer></main>;
}
